package com.nextrade.engine.risk; public final class MaxOrderQuantityRule implements RiskRule { private final com.nextrade.common.valueobject.Quantity max; public MaxOrderQuantityRule(com.nextrade.common.valueobject.Quantity max){this.max=max;} public RiskDecision evaluate(RiskContext context){return context.orderQuantity().compareTo(max)<=0?RiskDecision.allow():RiskDecision.block("MAX_QTY","Order quantity exceeds limit");} public String name(){return "MAX_ORDER_QUANTITY";} }